contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);
        c.play{value: amount}(); if (__ESBMC_reverted()) return;
        uint potBefore = 0;
        // pot before this call equals c.pot() minus our contribution if we just played;
        // instead track balance before by reading after the call is impossible, so do two plays
        // Simpler: capture state via a first no-op read is impossible; use a second play framing.
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;
        assert(c.pot() == 0 || (c.pot() == potAfter && address(c).balance == balAfter));
    }
    receive() external payable {}
}

